mapper.update:
UPDATE dsip_trackers
SET status = #{status}
WHERE tracker_id = #{trackerId}

UPDATE dsip_trackers
SET total_capital_invested_so_far = total_capital_invested_so_far + #{executedAmount},
    shares_held_so_far = shares_held_so_far + #{sharesBought},
    active_partition_index = #{activePartitionIndex}
WHERE tracker_id = #{trackerId}

mapper.select:
SELECT *
FROM dsip_partitions
WHERE tracker_id = #{trackerId}
  AND partition_index = #{partitionIndex}

SELECT * FROM dsip_executions
WHERE tracker_id = #{trackerId}
ORDER BY created_at DESC
LIMIT #{limit}

SELECT * FROM dsip_executions
WHERE partition_id = #{partitionId}
ORDER BY created_at ASC
